import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // --- Quote: base premiums per item type (parallel catalogue: one test per entry) ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a plain sword as 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quotes a plain amulet as 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff as 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion as 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune as 32.5 -> 33 G (25 base + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("quotes a single moonstone as 32.5 -> 33 G (25 base + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("rejects a quote with an unknown item type ('broomstick') by throwing an Error");

  // --- Quote: component building blocks ---
  it.todo("quotes 2 runes at base premium 50 G (no block)");
  it.todo("quotes 3 runes at base premium 60 G (block applies)");
  it.todo("quotes 4 runes at base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes at base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone at base premium 75 G (no block: 'alike' means same type)");
  it.todo("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed item's base premium");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5");
  it.todo("adds no high-enchantment surcharge at enchantment 4");
  it.todo("adds both curse and high-enchantment surcharges to a cursed item with enchantment exactly 5");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge to each item in every quote, regardless of customer history");
  it.todo("applies a 15 % follow-up discount on the customer's second quote but not on the first");
  it.todo("adds the 5 G processing fee at the very end, after all other modifiers");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge to the cursed item's base premium only: cursed sword + plain amulet -> 210 G before further modifiers and fee");

  // --- Quote: rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("newcomer with a cursed steel sword (enchantment 3), 0 years -> premium 165 G");
  it.todo("long-standing customer's (3 years) second quote, cursed steel sword (enchantment 7) -> premium 160 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (500 - 100 deductible)");
  it.todo("pays out 100 G for a damaged rune (250 G value) with 200 G damage (no enchantment/material clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50 % for damage to an item with enchantment exactly 8: dragon sword, 1000 G damage -> payout 400 G");
  it.todo("fully reimburses dragon-material damage: dragon sword enchantment 5, 800 G damage -> payout 700 G");
  it.todo("lets the 50 % rule win over dragon material: dragon sword enchantment 9, 1000 G damage -> payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword enchantment 9, 1000 G damage -> payout 400 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a two-sword policy at 4000 G (insurance sum 2000 G, cap = 2x)");
  it.todo("caps a sword + amulet policy at 3200 G (insurance sum 1600 G)");
  it.todo("bases the cap on unmodified insurance values: cursed sword -> cap 2000 G despite premium modifiers");
  it.todo("counts component insurance values in full: sword + 3 runes (a block) -> insurance sum 1750 G, cap 3500 G");
  it.todo("reports remainingCap 600 G after a first 1500 G claim on a 2000 G cap (payout 1400 G)");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damages entry as a separate damage with its own deductible when two swords are insured");
  it.todo("rejects a claim with more damage entries of a type than the policy covers by throwing an Error");

  // --- Claim: rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Claim: rejection cases ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim whose damaged item has an unknown type by throwing an Error");
  it.todo("rejects a claim containing a damage entry with a negative amount (-200) by throwing an Error");

  // --- Scenario processing ---
  it.todo("processes steps sequentially and returns one result per step in order");
  it.todo("resolves a claim's policy field as the zero-based index of the quote step that created the policy");
  it.todo("runs the schema example end to end: 5-year customer, silver amulet quote then 200 G amulet claim");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} JSON to stdout with exit code 0");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an unknown quote item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for a claim on an item not in the policy");
  it.todo("CLI exits with a non-zero status and writes an error description to stderr for a negative damage amount");
});

