python3 - <<'EOF'
import re
p='src/claim-office.spec.ts'
s=open(p).read()
s=s.replace('import { describe, it } from "vitest";','import { describe, expect, it } from "vitest";\nimport { runScenario } from "./claim-office.js";')
s=s.replace('''  it.todo("quotes an empty item list as 5 G (processing fee only)");''','''  it("quotes an empty item list as 5 G (processing fee only)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(results).toEqual([{ premium: 5 }]);
  });''')
open(p,'w').write(s)
