  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;

interface Policy {
  items: ItemInput[];
  remainingCap: number;
}

function insuranceSum(items: ItemInput[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

function openPolicy(items: ItemInput[]): Policy {
  return { items, remainingCap: insuranceSum(items) * CAP_FACTOR };
}

function reimbursementFor(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

function settleClaim(policy: Policy, damages: Damage[]): StepResult {
  const desiredPayout = damages.reduce(
    (total, damage) => total + reimbursementFor(damage),
